Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CE.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x6 x7 x11 x13 x15 x16 x22 x23 x27 x29 : word).
  Variables (m : fmem) (DT SY b e tb tl sym1 : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= SY \/ SY + 256 <= DT + 4.
  Hypothesis HSY : 0 < SY /\ SY + 256 <= 2^47.
  Hypothesis HTB : 1 <= tb <= 12.
  Hypothesis HTL : 4 <= tl - tb <= 11.
  Hypothesis HS1 : 0 <= sym1 < 256.
  Hypothesis HBE : 0 <= b <= e /\ e <= 256.
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).
  Notation D2 := (sym1 + tb * 65536 + 33554432).
  Notation LEN := (2 ^ (tl - tb)).
  Notation UU sym := (Z.lor (Z.lor (sym * 256) D2 ≪ 32 mod 18446744073709551616) (Z.lor (sym * 256) D2)).

  (* [comment removed for export] *)
  Lemma c2e_chunks : forall n sym c s u dt1 v m1 dtR (x5 x10 x26 : word),
    c = build_x2 sym tb sym1 2 -> 0 <= sym < 256 ->
    store_run (8 * n) dt1 v c = Ok dtR -> 0 <= v -> v + 8 * Z.of_nat n = u + LEN -> (0 < n)%nat -> INV m1 dt1 ->
    (forall m2 (y5 y10 y26 : word), INV m2 dtR ->
       evt psegs POST (MS (mkR x1 sp gp tp y5 x6 x7 (Z_to_bv 64 D2) (Z_to_bv 64 (UU sym)) y10 x11
                               (Z_to_bv 64 (Z.lor sym1 33554432)) x13 (Z_to_bv 64 (DT + 4 + 4 * (u + LEN))) x15 x16
                               (Z_to_bv 64 (SY + s)) (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8)
                               (Z_to_bv 64 (DT + 4 + 4 * (u + LEN))) x22 x23 (Z_to_bv 64 SY) (Z_to_bv 64 (4 * LEN)) y26 x27
                               (Z_to_bv 64 (SY + e)) x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x14270) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 D2) (Z_to_bv 64 (UU sym)) x10 x11
                            (Z_to_bv 64 (Z.lor sym1 33554432)) x13 (Z_to_bv 64 (DT + 4 + 4 * (u + LEN))) x15 x16
                            (Z_to_bv 64 (SY + s)) (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8)
                            (Z_to_bv 64 (DT + 4 + 4 * v)) x22 x23 (Z_to_bv 64 SY) (Z_to_bv 64 (4 * LEN)) x26 x27
                            (Z_to_bv 64 (SY + e)) x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
