  Lemma c2e_outer : forall f s dt u m1 r (x5 x9 x10 x21 x26 : word),
    fill_for_weight f dt u s e tb tl sym1 2 sorted = Ok r ->
    Z.of_nat f = e - s + 1 -> b <= s < e -> 0 <= u -> INV m1 dt ->
    (forall m2 dt' (y5 y9 y10 y14 y17 y21 y26 : word),
       r = (dt', u + LEN * (e - s)) -> INV m2 dt' ->
       evt psegs POST (MS (mkR x1 sp gp tp y5 x6 x7 (Z_to_bv 64 D2) y9 y10 x11 (Z_to_bv 64 (Z.lor sym1 33554432)) x13 y14
                               x15 x16 y17 (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) y21 x22 x23 (Z_to_bv 64 SY)
                               (Z_to_bv 64 (4 * LEN)) y26 x27 (Z_to_bv 64 (SY + e)) x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x140c4) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 D2) x9 x10 x11 (Z_to_bv 64 (Z.lor sym1 33554432)) x13
                            (Z_to_bv 64 (DT + 4 + 4 * u)) x15 x16 (Z_to_bv 64 (SY + s)) (Z_to_bv 64 2) (Z_to_bv 64 4)
                            (Z_to_bv 64 8) x21 x22 x23 (Z_to_bv 64 SY) (Z_to_bv 64 (4 * LEN)) x26 x27
                            (Z_to_bv 64 (SY + e)) x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
